@implementation HabitDB

- (void)initialize {
    self.connection = [[SQLiteConnection alloc] initWithDatabaseFile:@"habits.db"];
    self.defaultEncoder = [NSPropertyListEncoder defaultEncoder];
    self.defaultDecoder = [NSPropertyListDecoder defaultDecoder];
}

- (void)closeConnection {
    [connection close];
}

- (void)addHabit:(Habit *)habit {
    [connection runInTransaction^] {
        NSString *sql = @"
            INSERT INTO habits (name, frequency, is_completed)
            VALUES (?, ?, ?)
        ";
        [connection executeStatementWithSQLString:sql
            withParameters:@[@(habit.name), @([habit.frequency stringWithUTF16ScalarValues]), @([habit.isCompleted integer])]
            usingBlock:^(SQLiteStatement *statement, NSError *error) {
                if (error) {
                    NSLog(@"Error inserting: %@", error);
                }
            }];
    };
}

- (void)updateHabit:(Habit *)habit {
    [connection runInTransaction^] {
        NSString *sql = @"
            UPDATE habits
            SET name = ?, frequency = ?, is_completed = ?
            WHERE id = 1
        ";
        [connection executeStatementWithSQLString:sql
            withParameters:@[@(habit.name), @([habit.frequency stringWithUTF16ScalarValues]), @([habit.isCompleted integer])]
            usingBlock:^(SQLiteStatement *statement, NSError *error) {
