#include <iostream>
#include <memory>
#include <vector>
#include <algorithm>

struct Person {
    std::string name;
    int age;
};

int main() {
    std::vector<std::unique_ptr<Person>> people = {
        std::make_unique<Person>{ "Alice", 30 },
        std::make_unique<Person>{ "Bob", 25 },
        std::make_unique<Person>{ "Charlie", 35 }
    };

    // Sort people by age using a lambda as the comparator
    std::sort(people.begin(), people.end(),
        [](const std::unique_ptr<Person>& a, const std::unique_ptr<Person>& b) {
            return a->age < b->age;
        });

    // Range-based for loop to print each person
    for (const auto& person : people) {
        std::cout << person->name << " is " << person->age << " years old." << std::endl;
    }

    return 0;
}
